int get_inner_1bufATRSL(int InpATRCoeff, 
                        bool InpTrailEna, 
                        bool InpATREna, 
                        bool InpTEMAEna, 
                        ATRSLBUF_struct &ATRSL1BUF,
                        double handle_iTEMA, 
                        double handle_iATR)
{
    double loss;

    int array_size = ArraySize(ATRSL1BUF.ATRLV);
    ATRSL1BUF.log = "";
    if(array_size < 2){
      Print("array size cannot less than 2 at function:", __FUNCTION__, " ", __LINE__, " ERROR: ", GetLastError());
      return -1;
    }
    
    int i = array_size - 1;
    int j = i-1;

    if(InpTEMAEna){
      if(CopyBuffer(handle_iTEMA,0,0,array_size, ATRSL1BUF.ATRSLMid) < 0){
         Print("iTEMA copybuffer issue at function:", __FUNCTION__, " ", __LINE__, " ERROR: ", GetLastError());
         return -1;
      }
    }
    else {
      if (CopyClose(_Symbol, _Period, 0, array_size, ATRSL1BUF.ATRSLMid) < 0){
         Print("CopyClose issuet at function:", __FUNCTION__, " ", __LINE__, " ERROR: ", GetLastError());
         return -1;
      }
    }

    if(InpATREna){
      if (CopyBuffer(handle_iATR, 0, 0, array_size, ATRSL1BUF.ATRVal) < 0){
         Print("iATR copybuffer issuet at function:", __FUNCTION__, " ", __LINE__, " ERROR: ", GetLastError());
         return -1;
      }
      loss = ATRSL1BUF.ATRVal[i]*InpATRCoeff;
    }

    if(ATRSL1BUF.BufferTMP[i] == 0) // unconfirm buffertmp is upper or lower
    {
        static double first_tmp_upper = ATRSL1BUF.ATRSLMid[i] + loss;
        static double first_tmp_lower = ATRSL1BUF.ATRSLMid[i] - loss;
        double prev_tmp_upper = first_tmp_upper;
        double prev_tmp_lower = first_tmp_lower;
        first_tmp_upper = fmin(prev_tmp_upper, ATRSL1BUF.ATRSLMid[j] + loss);

double prev_tmp_upper = first_tmp_upper;
        double prev_tmp_lower = first_tmp_lower;
        first_tmp_upper = fmin(prev_tmp_upper, ATRSL1BUF.ATRSLMid[j] + loss);
        first_tmp_lower = fmax(prev_tmp_lower, ATRSL1BUF.ATRSLMid[j] - loss);
      //   ATRSL1BUF.log += ", upper:[" + (string)NormalizeDouble(first_tmp_upper, Digits) + "]";
      //   ATRSL1BUF.log += ", lower:[" + (string)NormalizeDouble(first_tmp_lower, Digits) + "]";

        // check first crossed over, if TEMA crossed up atrupper then, tmp is upper
        if(ATRSL1BUF.ATRSLMid[i]>first_tmp_upper)
        {
            ATRSL1BUF.BufferTMP[j] = prev_tmp_lower;
            ATRSL1BUF.BufferTMP[i] = first_tmp_lower;
            ATRSL1BUF.log += " BufferTMP =first_tmp_lower =" + (string)NormalizeDouble(first_tmp_lower, Digits);
        }
        else if(ATRSL1BUF.ATRSLMid[i]<first_tmp_lower)
        {
            ATRSL1BUF.BufferTMP[j] = prev_tmp_upper;
            ATRSL1BUF.BufferTMP[i] = first_tmp_upper;
            ATRSL1BUF.log += " BufferTMP =first_tmp_upper =" + (string)NormalizeDouble(first_tmp_upper, Digits);
        }
    }
    else
    {    // confirmed the tmp is upper or lower
        for(int v=1; v<=(array_size-1); v++){
            ATRSL1BUF.BufferTMP[v-1] = ATRSL1BUF.BufferTMP[v]; 
            ATRSL1BUF.ATRLV[v-1] = ATRSL1BUF.ATRLV[v];
            ATRSL1BUF.ATRSLLower[v-1] = ATRSL1BUF.ATRSLLower[v];
            ATRSL1BUF.ATRSLUpper[v-1] = ATRSL1BUF.ATRSLUpper[v];
            ATRSL1BUF.ATRTrend[v-1] = ATRSL1BUF.ATRTrend[v];
        }

        if(ATRSL1BUF.ATRSLMid[i]>ATRSL1BUF.BufferTMP[j] && ATRSL1BUF.ATRSLMid[j]>ATRSL1BUF.BufferTMP[j]) // tmp is ATRSLLower
        {
            ATRSL1BUF.dir = 0;
            ATRSL1BUF.log += " dir:" + ATRSL1BUF.dir;
            ATRSL1BUF.ATRTrend[i] = 2.0;
            ATRSL1BUF.BufferTMP[i]=fmax(ATRSL1BUF.BufferTMP[j],ATRSL1BUF.ATRSLMid[i]-loss);
            ATRSL1BUF.ATRLV[i]=ATRSL1BUF.BufferTMP[i];

ATRSL1BUF.ATRTrend[i] = 2.0;
            ATRSL1BUF.BufferTMP[i]=fmax(ATRSL1BUF.BufferTMP[j],ATRSL1BUF.ATRSLMid[i]-loss);
            ATRSL1BUF.ATRLV[i]=ATRSL1BUF.BufferTMP[i];
            if(InpTrailEna)
            {
                ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.BufferTMP[i];
                if(ATRSL1BUF.ATRSLMid[i]<ATRSL1BUF.ATRSLUpper[j] && ATRSL1BUF.ATRSLMid[j]<ATRSL1BUF.ATRSLUpper[i]) 
                    ATRSL1BUF.ATRSLUpper[i]=fmin(ATRSL1BUF.ATRSLUpper[j],ATRSL1BUF.ATRSLMid[i]+loss);
                else
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
            }
            else{
                ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;
            }
        }
        else
        {
            if(ATRSL1BUF.ATRSLMid[i]<ATRSL1BUF.BufferTMP[j] && ATRSL1BUF.ATRSLMid[j]<ATRSL1BUF.BufferTMP[j])
            {
                ATRSL1BUF.dir = 1;
                ATRSL1BUF.log += " dir:" + ATRSL1BUF.dir;
                ATRSL1BUF.ATRTrend[i] = 1.0;
                ATRSL1BUF.BufferTMP[i]=fmin(ATRSL1BUF.BufferTMP[j],ATRSL1BUF.ATRSLMid[i]+loss);
                ATRSL1BUF.ATRLV[i]=ATRSL1BUF.BufferTMP[i];
                if(InpTrailEna)
                {
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.BufferTMP[i];
                    // set ATRSLLower to be max else reset back to ori ATRSLLower
                    if(ATRSL1BUF.ATRSLMid[i]>ATRSL1BUF.ATRSLLower[j] && ATRSL1BUF.ATRSLMid[j]>ATRSL1BUF.ATRSLLower[j])
                        ATRSL1BUF.ATRSLLower[i]=fmax(ATRSL1BUF.ATRSLLower[j],ATRSL1BUF.ATRSLMid[i]-loss);
                    else
                        ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;
                }
                else{
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                    ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;

}
                else{
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                    ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;
                }
            }
            else
            {
                if(ATRSL1BUF.ATRSLMid[i]>ATRSL1BUF.BufferTMP[j]) // updat atr to be lower
                {
                    ATRSL1BUF.dir = 0;
                    ATRSL1BUF.log += " dir:" + ATRSL1BUF.dir;
                    ATRSL1BUF.ATRTrend[i] = 2.0;
                    ATRSL1BUF.BufferTMP[i]=ATRSL1BUF.ATRSLMid[i]-loss;
                    ATRSL1BUF.ATRLV[i]=ATRSL1BUF.BufferTMP[i];
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                    ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;
                }
                else
                {   // update atr to be upper
                    ATRSL1BUF.dir = 1;
                    ATRSL1BUF.log += " dir:" + ATRSL1BUF.dir;
                    ATRSL1BUF.ATRTrend[i] = 1.0;
                    ATRSL1BUF.BufferTMP[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                    ATRSL1BUF.ATRLV[i]=ATRSL1BUF.BufferTMP[i];
                    ATRSL1BUF.ATRSLUpper[i]=ATRSL1BUF.ATRSLMid[i]+loss;
                    ATRSL1BUF.ATRSLLower[i]=ATRSL1BUF.ATRSLMid[i]-loss;
                }
            }
        }
    }

   ATRSL1BUF.log += ", Trend:[";
   for(int a=array_size-1; a != 0; a--){
      ATRSL1BUF.log += (string)NormalizeDouble(ATRSL1BUF.ATRTrend[a], Digits) + ",";
   }
   ATRSL1BUF.log += "]";

   ATRSL1BUF.log += ", LV:[";
   for(int a=array_size-1; a != 0; a--){
