   }
   ATRSL1BUF.log += "]";

   ATRSL1BUF.log += ", Upper:[";
   for(int a=array_size-1; a != 0; a--){
      ATRSL1BUF.log += (string)NormalizeDouble(ATRSL1BUF.ATRSLUpper[a], Digits) + ",";
   }
   ATRSL1BUF.log += "]";

   ATRSL1BUF.log += ", Lower:[";

for(int a=array_size-1; a != 0; a--){
      ATRSL1BUF.log += (string)NormalizeDouble(ATRSL1BUF.ATRSLUpper[a], Digits) + ",";
   }
   ATRSL1BUF.log += "]";

   ATRSL1BUF.log += ", Lower:[";
   for(int a=array_size-1; a != 0; a--){
      ATRSL1BUF.log += (string)NormalizeDouble(ATRSL1BUF.ATRSLLower[a], Digits) + ",";
