int update_array_num(ENUM_BB_TF &array_num, string Ind_TIMEFRAME)
{
   if(Ind_TIMEFRAME == "M5")
   {
      array_num = 0;
   }
   else if(Ind_TIMEFRAME == "M15")
   {
      array_num = 1;
   }
   else if(Ind_TIMEFRAME == "M30")
   {
      array_num = 2;
   }
   else if(Ind_TIMEFRAME == "H1")
   {
      array_num = 3;
   }
   else if(Ind_TIMEFRAME == "H4")
   {
      array_num = 4;
   }
   else if(Ind_TIMEFRAME == "D1")
   {
      array_num = 5;
   }
   else if(Ind_TIMEFRAME == "W1")
   {
      array_num = 6;
   }
   else
   {
      return -1;
   }

   return 0;
}

