void BBTFImpact_Price_Dist_2_BBLines(BB_MTF_Impact_struct &BBTFImpact, BB_MTF_Data_struct &BB_datas[], double &close_prices[], double &high_prices[], double &low_prices[])
{
   string BB_CloseDist2BBLines_info = "";
   string checkhigh_info = "";
   string checklow_info = "";

   for(int j=TF2arraynum(_Period); j < ArraySize(BB_datas); j++)
   {
      for(int k=0; k < 4; k++)
      {
         BB_datas[j].BB_CloseDist2BBLines[k][LA_4] = BB_datas[j].BB_CloseDist2BBLines[k][LA_3];
         BB_datas[j].BB_CloseDist2BBLines[k][LA_3] = BB_datas[j].BB_CloseDist2BBLines[k][LA_2];
         BB_datas[j].BB_CloseDist2BBLines[k][LA_2] = BB_datas[j].BB_CloseDist2BBLines[k][LA_1];
         BB_datas[j].BB_CloseDist2BBLines[k][LA_1] = BB_datas[j].BB_CloseDist2BBLines[k][LA];
         BB_datas[j].BB_CloseDist2BBLines[k][LA] = 0.0;
      }
      
      for(int k=0; k < 4; k++)
      {
         BB_datas[j].BB_HighLowDist2BBLines[k][LA_4] = BB_datas[j].BB_HighLowDist2BBLines[k][LA_3];
         BB_datas[j].BB_HighLowDist2BBLines[k][LA_3] = BB_datas[j].BB_HighLowDist2BBLines[k][LA_2];
         BB_datas[j].BB_HighLowDist2BBLines[k][LA_2] = BB_datas[j].BB_HighLowDist2BBLines[k][LA_1];

BB_datas[j].BB_HighLowDist2BBLines[k][LA_2] = BB_datas[j].BB_HighLowDist2BBLines[k][LA_1];
         BB_datas[j].BB_HighLowDist2BBLines[k][LA_1] = BB_datas[j].BB_HighLowDist2BBLines[k][LA];
         BB_datas[j].BB_HighLowDist2BBLines[k][LA] = 0.0;
      }

      BB_datas[j].BB_CloseDist2BBLines[3][LA] =  BB_datas[j].BBUppLV[LA] - close_prices[LA] ;
      BB_datas[j].BB_CloseDist2BBLines[2][LA] =  close_prices[LA] - BB_datas[j].BBMidLV[LA];
      // positive will be upp, negative will be lower
      BB_datas[j].BB_CloseDist2BBLines[1][LA] =  BB_datas[j].BBMidLV[LA] - close_prices[LA];
      BB_datas[j].BB_CloseDist2BBLines[0][LA] =  close_prices[LA] - BB_datas[j].BBLowLV[LA];

      // due to the LA value inaccurate, must use prev val
      // dist_high2BBUp 
      BB_datas[j].BB_HighLowDist2BBLines[3][LA] = BB_datas[j].BBUppLV[LA] - high_prices[LA_1];
      // dist_low2BBMidUp 
      BB_datas[j].BB_HighLowDist2BBLines[2][LA] = low_prices[LA_1] - BB_datas[j].BBMidLV[LA];
      //dist_high2BBMidDn 
      BB_datas[j].BB_HighLowDist2BBLines[1][LA] = BB_datas[j].BBMidLV[LA] - high_prices[LA_1];
      // dist_low2BBDn 
      BB_datas[j].BB_HighLowDist2BBLines[0][LA] = low_prices[LA_1] - BB_datas[j].BBLowLV[LA];

      BB_CloseDist2BBLines_info += "Dist" + "_" + arraynum_2_string(j) + ":[";
      for(int k=0; k < 4; k++)
      {
         if(k != 0)
         {
            BB_CloseDist2BBLines_info += ", ";
         }
         BB_CloseDist2BBLines_info += NormalizeDouble(BB_datas[j].BB_HighLowDist2BBLines[k][LA], 2);
      }
      BB_CloseDist2BBLines_info += "] ";
   }
   checkhigh_info += "High" + ":[";
   checkhigh_info += NormalizeDouble(high_prices[LA], 2) + ", " + NormalizeDouble(high_prices[LA_1], 2) + ", " + NormalizeDouble(high_prices[LA_2], 2);

   checklow_info += "Low" + ":[";

checkhigh_info += NormalizeDouble(high_prices[LA], 2) + ", " + NormalizeDouble(high_prices[LA_1], 2) + ", " + NormalizeDouble(high_prices[LA_2], 2);

   checklow_info += "Low" + ":[";
   checklow_info += NormalizeDouble(low_prices[LA], 2) + ", " + NormalizeDouble(low_prices[LA_1], 2) + ", " + NormalizeDouble(low_prices[LA_2], 2);

}

