   if(BB_data.BB_trend[LA_2] != 0) BB_data.BB_trend[LA_3] = BB_data.BB_trend[LA_2];
   if(BB_data.BB_trend[LA_1] != 0) BB_data.BB_trend[LA_2] = BB_data.BB_trend[LA_1];
   if(BB_data.BB_trend[LA] != 0) BB_data.BB_trend[LA_1] = BB_data.BB_trend[LA];

