void BBData_Get_BBUpDn_State(BB_MTF_Impact_struct &BBTFImpact, BB_MTF_Data_struct &BB_data, string &STRATEGY_info)
{
   if(BB_data.BBUpDn_state[LA_3] != -1) BB_data.BBUpDn_state[LA_4] = BB_data.BBUpDn_state[LA_3];
   if(BB_data.BBUpDn_state[LA_2] != -1) BB_data.BBUpDn_state[LA_3] = BB_data.BBUpDn_state[LA_2];
   if(BB_data.BBUpDn_state[LA_1] != -1) BB_data.BBUpDn_state[LA_2] = BB_data.BBUpDn_state[LA_1];
   if(BB_data.BBUpDn_state[LA] != -1) BB_data.BBUpDn_state[LA_1] = BB_data.BBUpDn_state[LA];

   // expanding, BBUpp > , BBLow < 
   if(BB_data.BBUppLV[LA] > BB_data.BBUppLV[LA_1] && BB_data.BBLowLV[LA] <  BB_data.BBLowLV[LA_1] && \

// expanding, BBUpp > , BBLow < 
   if(BB_data.BBUppLV[LA] > BB_data.BBUppLV[LA_1] && BB_data.BBLowLV[LA] <  BB_data.BBLowLV[LA_1] && \
