   {
      BB_data.BBUpDn_state[LA] = 1;
   }
   // strinking
   else if(BB_data.BBUppLV[LA] < BB_data.BBUppLV[LA_1] && BB_data.BBLowLV[LA] >  BB_data.BBLowLV[LA_1] && \
      BB_data.BBUppLV[LA_1] < BB_data.BBUppLV[LA_2] && BB_data.BBLowLV[LA_1] >  BB_data.BBLowLV[LA_2])
   {
      BB_data.BBUpDn_state[LA] = 2;
   }
   // up
   else if(BB_data.BBUppLV[LA] > BB_data.BBUppLV[LA_1] && BB_data.BBLowLV[LA] >  BB_data.BBLowLV[LA_1] && \
      BB_data.BBUppLV[LA_1] > BB_data.BBUppLV[LA_2] && BB_data.BBLowLV[LA_1] >  BB_data.BBLowLV[LA_2])
   {
      BB_data.BBUpDn_state[LA] = 3;
   }
   // dn
   else if(BB_data.BBUppLV[LA] < BB_data.BBUppLV[LA_1] && BB_data.BBLowLV[LA] <  BB_data.BBLowLV[LA_1] && \
      BB_data.BBUppLV[LA_1] < BB_data.BBUppLV[LA_2] && BB_data.BBLowLV[LA_1] <  BB_data.BBLowLV[LA_2])
   {
      BB_data.BBUpDn_state[LA] = 4;
   }
   else 
   {
      BB_data.BBUpDn_state[LA] = 0;
   }

   if(BB_data.BBUpDn_state[LA] >= 0)
      STRATEGY_info += ", BBUpDn_state_" + arraynum_2_string(BBTFImpact.array_num) + ":" + EnumToString(BB_data.BBUpDn_state[LA]);
}

