   double SWD_diffBBW_SW_threshold = BBThres.SWD_diffBBW_SW_threshold;
   double SWD_diffMid_SW_threshold = BBThres.SWD_diffMid_SW_threshold;

   BB_data.BBW_updated_stage[LA] = 0;

   // verify HTF are strinking as it will impact current squeeze
   // verify which HTF has squeezed 
   // verify targeted squeezed HTF

   // if verify HTF strink, need inform squeeze is strong_M15_wait
   // M5_sqz -> M15_strink -> M30_strink -> H1_strink
   // M5_fly -> M15_sqz -> M30_strink -> H1_strink -> H4_strink
   // M5_fly -> M15_sqz -> M30_strink -> H1_strink -> H4_strink

// M5_sqz -> M15_strink -> M30_strink -> H1_strink
   // M5_fly -> M15_sqz -> M30_strink -> H1_strink -> H4_strink
   // M5_fly -> M15_sqz -> M30_strink -> H1_strink -> H4_strink
   // M5_fly -> M15_fly -> M30_strink -> H1_strink -> H4_sqz
   // due to strink hard to trace, we only detect which has squzzed 

   dlog += "G4";
   // G41 perform sideway 
   if((BB_data.BBWLV[LA] <= BBW_SQ_threshold || BB_data.BBWLV[LA_1] <= BBW_SQ_threshold) \
      && BB_data.BB_diffBBW[LA] < diffBBW_SQ_threshold && BB_data.BB_diffBBW[LA] > -diffBBW_SQ_sideway_strink_threshold && \
      BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_sideway_strink_threshold && BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_sideway_strink_threshold && \
      BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_sideway_strink2_threshold && BB_data.BB_diffMid_Trend[LA] >= 3)
   {
      dlog += "1"; // G41
