   }
   // G42 when strong squeezed 
   // else if((BBWLV[LA] <= BBW_SQ_threshold || BBWLV[LA_1] <= BBW_SQ_threshold) && 
   else if(\
      BB_data.BB_diffBBW[LA] > diffBBW_SQ_strong_fly_threshold && \
      BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_mid_strink_threshold \
      && BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_strong_strink_threshold && \
      BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_strong_strink_threshold) // when strong squeezed
   {
      dlog += "2";
      // BBW_stage[LA] = 420;
      if(BB_data.BBWLV[LA] <= BBW_SQ_threshold)
      {
         dlog += "1";
         BB_data.BBW_stage[LA] = 420;
      }
      else if(BB_data.BBWLV[LA] <= BBW_SW_threshold)
      {
         dlog += "2";
         BB_data.BBW_stage[LA] = 410;
      }
      else 
      {
         dlog += "3";
         BB_data.BBW_stage[LA] = 400;
      }
   }
   // G43
   else if( BB_data.BB_diffBBW[LA] > diffBBW_SQ_strong_fly_threshold && \
      BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_mid_strink_threshold \

}
   }
   // G43
   else if( BB_data.BB_diffBBW[LA] > diffBBW_SQ_strong_fly_threshold && \
      BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_mid_strink_threshold \
      && BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_mid_strink_threshold && \
      BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_strong_strink_threshold) // when strong squeezed
   {
      dlog += "3";
      if(BB_data.BBWLV[LA] <= BBW_SQ_threshold)
      {
         dlog += "1";
         BB_data.BBW_stage[LA] = 420;
      }
      else if(BB_data.BBWLV[LA] <= BBW_SW_threshold)
      {
         dlog += "2";
         BB_data.BBW_stage[LA] = 410;
      }
      else 
      {
         dlog += "3";
         BB_data.BBW_stage[LA] = 400;
      }
   }
   //  G44 when strong squeezed, diffBB > 3, -2 < diffBB_1 < 2, diffBB_2 < -10, diffBB_3 < -10  
   else if(BB_data.BB_diffBBW[LA] > diffBBW_SQ_strong_fly_threshold && (BB_data.BB_diffBBW[LA_1] >= -diffBBW_SQ_threshold && \
      BB_data.BB_diffBBW[LA_1] <= diffBBW_SQ_threshold) && BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_strong_strink2_threshold && \
      BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_strong_strink_threshold) // when strong squeezed
   {
      dlog += "4";
      if(BB_data.BBWLV[LA] <= BBW_SQ_threshold)
      {
         dlog += "1";
         BB_data.BBW_stage[LA] = 420;
      }
      else if(BB_data.BBWLV[LA] <= BBW_SW_threshold)
      {
         dlog += "2";
         BB_data.BBW_stage[LA] = 410;
      }
      else 
      {
         dlog += "3";
         BB_data.BBW_stage[LA] = 400;
      }
   }
   // G45
   else if((BB_data.BBWLV[LA] <= BBW_SQ_threshold || BB_data.BBWLV[LA_1] <= BBW_SQ_threshold) && \
      (BB_data.BB_diffBBW[LA] >= -diffBBW_SQ_threshold && BB_data.BB_diffBBW[LA] <= diffBBW_SQ_threshold) && \
      (BB_data.BB_diffBBW[LA_1] >= -diffBBW_SQ_threshold && BB_data.BB_diffBBW[LA_1] <= diffBBW_SQ_threshold) \
