      BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_mid_strink_threshold) // when strong squeezed
   {
      dlog += "5";
      BB_data.BBW_stage[LA] = 420;
   }
   // G47 when is squeeze, due to G47, M5 and M15 have LA_2 for diffBBW detection, others dont have  
   else if((BB_data.BB_diffBBW[LA] < diffBBW_SQ_sideway_strink_threshold) && (BB_data.BB_diffBBW[LA] > -diffBBW_SQ_sideway_strink_threshold) && \
      (BB_data.BB_diffBBW[LA_1] < diffBBW_SQ_sideway_strink_threshold) && (BB_data.BB_diffBBW[LA_1] > -diffBBW_SQ_sideway_strink_threshold) && \
