      (BB_data.BB_diffMid[LA] < diffMid_SQ_threshold) && (BB_data.BB_diffMid[LA] > -diffMid_SQ_threshold) && \
      (BB_data.BB_diffMid[LA_1] < diffMid_SQ_threshold) && (BB_data.BB_diffMid[LA_1] > -diffMid_SQ_threshold) && \
      (BB_data.BB_diffMid[LA_2] < diffMid_SQ_threshold) && (BB_data.BB_diffMid[LA_2] > -diffMid_SQ_threshold) && \
      (BB_data.BBWLV[LA] < BBW_SQ2_threshold || BB_data.BBWLV[LA_1] < BBW_SQ2_threshold))
      // && (Ind_TIMEFRAME == "M5" || Ind_TIMEFRAME == "M15")) // when no fly and squeeze detected
   {
      dlog += "7";
      BB_data.BBW_stage[LA] = 420;
   }
   // G48
   else if((BB_data.BB_diffBBW[LA] < diffBBW_SQ_sideway_strink2_threshold) && (BB_data.BB_diffBBW[LA] > -diffBBW_SQ_sideway_strink2_threshold) && \
      (BB_data.BB_diffBBW[LA_1] < diffBBW_SQ_sideway_strink2_threshold) && (BB_data.BB_diffBBW[LA_1] > -diffBBW_SQ_sideway_strink2_threshold) && \
      (BB_data.BB_diffBBW[LA_2] < diffBBW_SQ_sideway_strink2_threshold) && (BB_data.BB_diffBBW[LA_2] > -diffBBW_SQ_sideway_strink2_threshold) && \

(BB_data.BB_diffBBW[LA_2] < diffBBW_SQ_sideway_strink2_threshold) && (BB_data.BB_diffBBW[LA_2] > -diffBBW_SQ_sideway_strink2_threshold) && \
      (BB_data.BB_diffMid[LA] < diffMid_SQ2_threshold) && (BB_data.BB_diffMid[LA] > -diffMid_SQ2_threshold) && \
      (BB_data.BB_diffMid[LA_1] < diffMid_SQ2_threshold) && (BB_data.BB_diffMid[LA_1] > -diffMid_SQ2_threshold) && \
      (BB_data.BB_diffMid[LA_2] < diffMid_SQ2_threshold) && (BB_data.BB_diffMid[LA_2] > -diffMid_SQ2_threshold) && \
      (BB_data.BBWLV[LA] < BBW_SQ2_threshold || BB_data.BBWLV[LA_1] < BBW_SQ2_threshold)) // when no fly and squeeze detected
   {
      dlog += "8";
      BB_data.BBW_stage[LA] = 420;
   }
   // G49
   else if((BB_data.BBWLV[LA] <= BBW_SQ_threshold || BB_data.BBWLV[LA_1] <= BBW_SQ_threshold) && \
      BB_data.BB_diffBBW[LA] > diffBBW_SQ_strong_fly_threshold && BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_mid_strink_threshold \
      && ( BB_data.BB_diffBBW[LA_1] <= -diffBBW_SQ_strong_strink_threshold || BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_strong_strink_threshold) \
      && BB_data.BB_diffBBW[LA_2] <= -diffBBW_SQ_mid_strink_threshold && BB_data.BB_diffBBW[LA_3] <= -diffBBW_SQ_mid_strink_threshold) // when strong squeezed
   {
      dlog += "9";
      if(BB_data.BBWLV[LA] <= BBW_SQ_threshold)
      {
         dlog += "1";
         BB_data.BBW_stage[LA] = 420;
      }
      else if(BB_data.BBWLV[LA] <= BBW_SW_threshold)
      {
         dlog += "2";
         BB_data.BBW_stage[LA] = 410;
      }
      else 
      {
         dlog += "3";
         BB_data.BBW_stage[LA] = 400;
      }
